    # test a_gem_is_taken_once (hop/tests/touches.slg:10)
    def self.a_gem_is_taken_once
      Hop::World.step(Hop::Tests::Touches.rest)
      Spec.assert(Hop::World.taken == Spec::Sets.of([3]))
      Hop::World.step(Hop::Tests::Touches.rest)
      Spec.assert(Hop::World.taken == Spec::Sets.of([3]))
      Spec.assert(Spec.effect("cli.out", :text) == "1 gem 3\n")
    end
    SUITE.test(
      "hop.tests.touches.a_gem_is_taken_once",
      method(:a_gem_is_taken_once),
      given: [SUITE.after("hop.world.at_the_third_gem")]
    )

    # test a_fall_keeps_the_gems (hop/tests/touches.slg:19)
    # @why a life lost keeps the gems taken
    def self.a_fall_keeps_the_gems
      Hop::World.step(Hop::Tests::Touches.rest)
      Spec.assert(Hop::World.lives == 2)
      Spec.assert(Hop::World.taken == Spec::Sets.of([1]))
    end
    SUITE.test(
      "hop.tests.touches.a_fall_keeps_the_gems",
      method(:a_fall_keeps_the_gems),
      given: [SUITE.after("hop.world.about_to_fall_out_holding_a_gem")]
    )

