    # test a_stomp_removes_the_crawler (hop/tests/touches.slg:35)
    # @why falling onto the upper half of a crawler removes it and bounces
    def self.a_stomp_removes_the_crawler
      Hop::World.step(Hop::Tests::Touches.rest)
      Spec.assert(!Hop::World.crawlers.key?(1))
      Spec.assert(Hop::World.player.vel.y == 24)
      Spec.assert(Hop::World.lives == 3)
    end
    SUITE.test(
      "hop.tests.touches.a_stomp_removes_the_crawler",
      method(:a_stomp_removes_the_crawler),
      given: [SUITE.after("hop.world.falling_on_the_crawler")]
    )

    # test a_crawler_hurts_from_the_side (hop/tests/touches.slg:44)
    # @why walking into a crawler costs a life and restarts the hero
    def self.a_crawler_hurts_from_the_side
      Hop::World.step(Hop::Model::Pad.new(right: true))
      Spec.assert(Hop::World.lives == 2)
      Spec.assert(Hop::World.player.at == Hop::Levels.meadow.start)
