    # test starting_again_resets_everything (hop/tests/touches.slg:75)
    def self.starting_again_resets_everything
      Hop::World.start(1)
      Spec::Ranges.list((1..5)).each do |i|
        Hop::World.step(Hop::Model::Pad.new(right: true))
      end
      Hop::World.start(2)
